#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_resize_and_success(void) {
    // Setup: create a buffer with small initial size and some data
    // We'll append more data than fits, so buffer_resize is triggered and succeeds

    // Create buffer with initial content "abc" and small size (e.g., 4 bytes)
    buffer_t *buf = buffer_new_with_size(4);
    TEST_ASSERT_NOT_NULL(buf);
    strcpy(buf->data, "abc"); // 3 chars + '\0'
    // Confirm initial state
    helper_assert_buffer_string_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);
    helper_assert_buffer_size(buf, 4);

    // Prepare string to append
    const char *to_append = "XYZ";
    size_t append_len = 3; // append all 3 chars

    // This will require resize: needed = 3 (prev) + 3 (len) = 6 > 4 (buf->len)
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assert success
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Buffer should now contain "abcXYZ"
    helper_assert_buffer_string_equals(buf, "abcXYZ");
    helper_assert_buffer_length(buf, 6);

    // Buffer size should be at least 6 (likely rounded up by buffer_resize, but at least 6)
    TEST_ASSERT_TRUE(buffer_size(buf) >= 6);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_and_success);
    return UNITY_END();
}


